27	function findAgentFile(agentName) {
28	  if (!agentName || typeof agentName !== 'string') return null;
29	  const dir = path.join(CLAUDE_DIR, 'agents');
30	  if (!fs.existsSync(dir)) return null;
31	  const target = agentName.toLowerCase();
32	  for (const file of fs.readdirSync(dir)) {
33	    if (!file.endsWith('.md')) continue;
34	    const fname = file.replace(/\.md$/, '');
35	    if (fname === agentName || fname.toLowerCase() === target) return path.join(dir, file);
36	  }
37	  return null;
38	}
