44	function runClaudeSync(prompt, timeoutMs = 120000) {
45	  return new Promise((resolve, reject) => {
46	    const claudePath = process.env.CLAUDE_PATH || 'claude';
47	    const childEnv = { ...process.env, HOME: os.homedir() };
48	    delete childEnv.CLAUDECODE;
49	    delete childEnv.CLAUDE_CODE_ENTRYPOINT;
50	    delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
51	    delete childEnv.CLAUDE_AGENT_SDK_VERSION;
52	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
53	    let out = '', err = '';
54	    let killed = false;
55	
56	    const timer = setTimeout(() => {
57	      killed = true;
58	      proc.kill('SIGTERM');
59	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
60	    }, timeoutMs);
61	
62	    proc.stdout.on('data', d => { out += d.toString(); });
63	    proc.stderr.on('data', d => { err += d.toString(); });
64	    proc.on('close', code => {
65	      clearTimeout(timer);
66	      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
67	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
68	      else resolve(out.trim());
69	    });
70	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
71	    proc.stdin.write(prompt, 'utf8');
72	    proc.stdin.end();
73	  });
74	}
