76	function logAgentRun(entry) {
77	  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
78	  const estimateCost = (i, o) => (i * 3 + o * 15) / 1_000_000;
79	  const inputTokens = estimateTokens(entry.prompt || '');
80	  const outputTokens = estimateTokens(entry.output || '');
81	  const run = {
82	    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
83	    agentName: entry.agentName || 'unknown',
84	    prompt: (entry.prompt || '').slice(0, 200),
85	    source: entry.source || 'unknown',
86	    timestamp: new Date().toISOString(),
87	    duration: entry.duration || 0,
88	    status: entry.status || 'success',
89	    promptChars: (entry.prompt || '').length,
90	    outputChars: (entry.output || '').length,
91	    estimatedTokens: inputTokens + outputTokens,
92	    estimatedCost: estimateCost(inputTokens, outputTokens),
93	    error: entry.error || null,
94	    metadata: entry.metadata || {},
95	  };
96	  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }
97	  return run;
98	}
