104	  }
105	  const instructions = fs.readFileSync(file, 'utf-8');
106	  return `${instructions}\n\n---\n\n## Task:\n${schedule.prompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
