114	function startScheduleJob(schedule) {
115	  if (activeJobs.has(schedule.id)) {
116	    activeJobs.get(schedule.id).stop();
117	    activeJobs.delete(schedule.id);
118	  }
119	  if (!schedule.enabled) return;
120	  if (!cron.validate(schedule.cron)) {
121	    console.warn(`[schedule] invalid cron — job not scheduled: id=${schedule.id} name="${schedule.name}" cron="${schedule.cron}"`);
122	    return;
123	  }
124	
125	  const job = cron.schedule(schedule.cron, async () => {
126	    const startTime = Date.now();
127	    // Re-read fresh state so a paused/deleted schedule doesn't fire stale closure work
128	    const fresh = db.getScheduleById(schedule.id);
129	    if (!fresh || !fresh.enabled) return;
130	
131	    try {
132	      const prompt = buildScheduledPrompt(fresh);
133	      const output = await runClaudeSync(prompt, 300000);
134	      logAgentRun({
135	        agentName: fresh.agentName, prompt: fresh.prompt, output,
136	        source: 'schedule', duration: Date.now() - startTime, status: 'success',
137	        metadata: { scheduleId: fresh.id },
138	      });
139	      persistRunStatus(fresh.id, 'success');
140	    } catch (err) {
141	      logAgentRun({
142	        agentName: fresh.agentName, prompt: fresh.prompt, output: '',
143	        source: 'schedule', duration: Date.now() - startTime, status: 'error',
144	        error: err.message, metadata: { scheduleId: fresh.id },
145	      });
146	      persistRunStatus(fresh.id, 'error');
147	    }
148	  });
149	  activeJobs.set(schedule.id, job);
150	}
