152	function bootSchedules() {
153	  try {
154	    const schedules = db.loadSchedules();
155	    let active = 0;
156	    let invalid = 0;
157	    for (const s of schedules) {
158	      if (!s.enabled) continue;
159	      if (!cron.validate(s.cron)) {
160	        invalid++;
161	        console.warn(`[schedule] invalid cron at boot — skipping: id=${s.id} name="${s.name}" cron="${s.cron}"`);
162	        continue;
163	      }
164	      startScheduleJob(s);
165	      active++;
166	    }
167	    if (active > 0) console.log(`  Schedules: ${active} active cron job(s) restored`);
168	    if (invalid > 0) console.warn(`  Schedules: ${invalid} schedule(s) skipped due to invalid cron expressions`);
169	  } catch (err) {
170	    console.error('[bootSchedules] failed:', err.message);
171	  }
172	}
