224	router.put('/schedules/:id', rateLimit('write'), (req, res) => {
225	  const id = req.params.id;
226	  const existing = db.getScheduleById(id);
227	  if (!existing) return res.status(404).json({ error: 'Schedule not found' });
228	
229	  const { name, agentName, prompt, cronExpr, enabled } = req.body || {};
230	
231	  if (cronExpr !== undefined && !cron.validate(cronExpr)) {
232	    return res.status(400).json({ error: 'Invalid cron expression' });
233	  }
234	  if (agentName !== undefined && !validateAgentExists(agentName)) {
235	    return res.status(400).json({ error: `Agent '${agentName}' not found` });
236	  }
237	  if (name !== undefined && (typeof name !== 'string' || !name.trim())) {
238	    return res.status(400).json({ error: 'name cannot be empty' });
239	  }
240	  if (prompt !== undefined && (typeof prompt !== 'string' || !prompt.trim())) {
241	    return res.status(400).json({ error: 'prompt cannot be empty' });
242	  }
243	
244	  const fields = { updatedAt: new Date().toISOString() };
245	  if (name !== undefined) fields.name = name.trim();
246	  if (agentName !== undefined) fields.agentName = agentName.trim();
247	  if (prompt !== undefined) fields.prompt = prompt;
248	  if (cronExpr !== undefined) fields.cron = cronExpr;
249	  if (enabled !== undefined) fields.enabled = enabled;
250	
251	  try {
252	    db.updateScheduleFields(id, fields);
253	  } catch (err) {
254	    console.error('[schedules PUT] update failed:', err.message);
255	    return res.status(500).json({ error: 'Failed to update schedule' });
256	  }
257	
258	  const updated = db.getScheduleById(id);
259	  if (updated.enabled) {
260	    startScheduleJob(updated);
261	  } else if (activeJobs.has(id)) {
262	    activeJobs.get(id).stop();
263	    activeJobs.delete(id);
264	  }
265	
266	  res.json(updated);
267	});
